#!/usr/bin/env Rscript

.libPaths(c("~/R_libs_amd", .libPaths()))
Sys.setenv(PKG_CXXFLAGS="-O3 -march=native -mtune=native")

suppressPackageStartupMessages({
  library(pROC)
  library(PRROC)
})

# Configuration
# cell_type = "WGCNA"
# cell_type = "Smoothie"
cell_type = "Oli"
# cell_type = "hdWGCNA"
# cell_type = "SpaceX"

cat("========================================================\n")
cat(" PART 2: Compiling Extended Metrics & Bootstrapping\n")
cat("========================================================\n\n")

# Load the intermediate results generated by Part 1
report_dir <- file.path("/home/koe/BSNMani_application-main/Github_BSNMani/result", cell_type, "Unbiased_LOOCV_Report")
load_file <- file.path(report_dir, "LOOCV_Intermediate_Predictions.RData")

if(!file.exists(load_file)) {
  stop("ERROR: Could not find 'LOOCV_Intermediate_Predictions.RData'. Did Part 1 finish successfully?")
}
load(load_file)

# Safely lock in the value of 'n' to prevent a crash
n <- length(test_true_labels)

# A. Pooled Point Estimates (Standard LOOCV)
TP <- sum(test_predicted_labels == 1 & test_true_labels == 1)
TN <- sum(test_predicted_labels == 0 & test_true_labels == 0)
FP <- sum(test_predicted_labels == 1 & test_true_labels == 0)
FN <- sum(test_predicted_labels == 0 & test_true_labels == 1)

base_accuracy <- (TP + TN) / n

# Class 1 (Positive) Metrics
base_precision <- ifelse((TP + FP) == 0, 0, TP / (TP + FP))
base_recall <- ifelse((TP + FN) == 0, 0, TP / (TP + FN))
base_f1 <- ifelse((base_precision + base_recall) == 0, 0, 2 * (base_precision * base_recall) / (base_precision + base_recall))
base_specificity <- ifelse((TN + FP) == 0, 0, TN / (TN + FP))

# Class 0 (Negative) Metrics for Macro F1
prec_0 <- ifelse((TN + FN) == 0, 0, TN / (TN + FN))
rec_0 <- ifelse((TN + FP) == 0, 0, TN / (TN + FP))
f1_0 <- ifelse((prec_0 + rec_0) == 0, 0, 2 * (prec_0 * rec_0) / (prec_0 + rec_0))

# Extended Metrics
base_macro_f1 <- (base_f1 + f1_0) / 2
base_micro_f1 <- base_accuracy # In binary classification, Micro F1 = Accuracy

mcc_denom <- sqrt(as.numeric(TP + FP) * as.numeric(TP + FN) * as.numeric(TN + FP) * as.numeric(TN + FN))
base_mcc <- ifelse(mcc_denom == 0, 0, (TP * TN - FP * FN) / mcc_denom)

suppressWarnings({
  # FIX 2: Lock the ROC direction to prevent auto-flipping on poor samples
  roc_obj <- roc(test_true_labels, test_predicted_probs, direction = "<", quiet = TRUE)
  base_auc <- as.numeric(auc(roc_obj))
  
  # AUPRC Calculation
  fg <- test_predicted_probs[test_true_labels == 1]
  bg <- test_predicted_probs[test_true_labels == 0]
  base_auprc <- if(length(fg) > 0 & length(bg) > 0) pr.curve(scores.class0 = fg, scores.class1 = bg)$auc.integral else NA
})

# C. Bootstrapped Mean & Std (1,000 iterations)
set.seed(12345)
B <- 1000
boot_metrics <- matrix(NA, nrow = B, ncol = 10)
colnames(boot_metrics) <- c("Accuracy", "AUC", "Precision", "Recall", "F1_Score", "Specificity", "Macro_F1", "Micro_F1", "MCC", "AUPRC")

for(b in 1:B) {
  idx <- sample(1:n, n, replace = TRUE)
  b_true <- test_true_labels[idx]
  b_prob <- test_predicted_probs[idx]
  b_pred <- test_predicted_labels[idx]
  
  b_TP <- sum(b_pred == 1 & b_true == 1)
  b_TN <- sum(b_pred == 0 & b_true == 0)
  b_FP <- sum(b_pred == 1 & b_true == 0)
  b_FN <- sum(b_pred == 0 & b_true == 1)
  
  boot_metrics[b, "Accuracy"] <- (b_TP + b_TN) / n
  boot_metrics[b, "Micro_F1"] <- boot_metrics[b, "Accuracy"]
  
  if(length(unique(b_true)) == 2) {
    boot_metrics[b, "AUC"] <- as.numeric(auc(roc(b_true, b_prob, quiet = TRUE)))
    boot_metrics[b, "AUPRC"] <- pr.curve(scores.class0 = b_prob[b_true == 1], scores.class1 = b_prob[b_true == 0])$auc.integral
  }
  
  b_prec <- ifelse((b_TP + b_FP) == 0, 0, b_TP / (b_TP + b_FP))
  b_rec <- ifelse((b_TP + b_FN) == 0, 0, b_TP / (b_TP + b_FN))
  boot_metrics[b, "Precision"] <- b_prec
  boot_metrics[b, "Recall"] <- b_rec
  b_f1 <- ifelse((b_prec + b_rec) == 0, 0, 2 * (b_prec * b_rec) / (b_prec + b_rec))
  boot_metrics[b, "F1_Score"] <- b_f1
  boot_metrics[b, "Specificity"] <- ifelse((b_TN + b_FP) == 0, 0, b_TN / (b_TN + b_FP))
  
  b_prec_0 <- ifelse((b_TN + b_FN) == 0, 0, b_TN / (b_TN + b_FN))
  b_rec_0 <- ifelse((b_TN + b_FP) == 0, 0, b_TN / (b_TN + b_FP))
  b_f1_0 <- ifelse((b_prec_0 + b_rec_0) == 0, 0, 2 * (b_prec_0 * b_rec_0) / (b_prec_0 + b_rec_0))
  boot_metrics[b, "Macro_F1"] <- (b_f1 + b_f1_0) / 2
  
  b_mcc_denom <- sqrt(as.numeric(b_TP + b_FP) * as.numeric(b_TP + b_FN) * as.numeric(b_TN + b_FP) * as.numeric(b_TN + b_FN))
  boot_metrics[b, "MCC"] <- ifelse(b_mcc_denom == 0, 0, (b_TP * b_TN - b_FP * b_FN) / b_mcc_denom)
}

boot_mean <- colMeans(boot_metrics, na.rm = TRUE)
boot_std <- apply(boot_metrics, 2, sd, na.rm = TRUE)

# D. Save Comparison Report
cat("\n========================================================\n")
cat(" UNBIASED LOOCV PERFORMANCE COMPARISON (EXTENDED)\n")
cat("========================================================\n")
cat(sprintf("Accuracy  | Pooled: %.4f | Boot: %.4f ± %.4f\n", base_accuracy, boot_mean["Accuracy"], boot_std["Accuracy"]))
cat(sprintf("AUC       | Pooled: %.4f | Boot: %.4f ± %.4f\n", base_auc, boot_mean["AUC"], boot_std["AUC"]))
cat(sprintf("AUPRC     | Pooled: %.4f | Boot: %.4f ± %.4f\n", base_auprc, boot_mean["AUPRC"], boot_std["AUPRC"]))
cat(sprintf("MCC       | Pooled: %.4f | Boot: %.4f ± %.4f\n", base_mcc, boot_mean["MCC"], boot_std["MCC"]))
cat(sprintf("Micro F1  | Pooled: %.4f | Boot: %.4f ± %.4f\n", base_micro_f1, boot_mean["Micro_F1"], boot_std["Micro_F1"]))
cat(sprintf("Macro F1  | Pooled: %.4f | Boot: %.4f ± %.4f\n", base_macro_f1, boot_mean["Macro_F1"], boot_std["Macro_F1"]))
cat(sprintf("F1 Score  | Pooled: %.4f | Boot: %.4f ± %.4f\n", base_f1, boot_mean["F1_Score"], boot_std["F1_Score"]))
cat("========================================================\n")

metrics_df <- data.frame(
  Metric = c("Accuracy", "AUC", "AUPRC", "MCC", "Micro_F1", "Macro_F1", "Precision", "Recall", "F1_Score", "Specificity"), 
  Pooled_Estimate = round(c(base_accuracy, base_auc, base_auprc, base_mcc, base_micro_f1, base_macro_f1, base_precision, base_recall, base_f1, base_specificity), 4),
  Bootstrapped_Mean = round(c(boot_mean["Accuracy"], boot_mean["AUC"], boot_mean["AUPRC"], boot_mean["MCC"], boot_mean["Micro_F1"], boot_mean["Macro_F1"], boot_mean["Precision"], boot_mean["Recall"], boot_mean["F1_Score"], boot_mean["Specificity"]), 4),
  Bootstrapped_Std = round(c(boot_std["Accuracy"], boot_std["AUC"], boot_std["AUPRC"], boot_std["MCC"], boot_std["Micro_F1"], boot_std["Macro_F1"], boot_std["Precision"], boot_std["Recall"], boot_std["F1_Score"], boot_std["Specificity"]), 4)
)

write.csv(metrics_df, file.path(report_dir, "Final_Comparison_Metrics_Extended.csv"), row.names = FALSE)
preds_df <- data.frame(Sample_Index = 1:n, True_Label = test_true_labels, Predicted_Prob = round(test_predicted_probs, 4), Predicted_Label = test_predicted_labels, Selected_Q = selected_qs)
write.csv(preds_df, file.path(report_dir, "Final_Test_Predictions.csv"), row.names = FALSE)
write.csv(dic_log, file.path(report_dir, "Inner_Validation_DIC_Log.csv"), row.names = FALSE)

cat(sprintf("Extended comparison report successfully saved to:\n   %s\n", report_dir))